def section_html(chapters):
    return ''.join(f'<section class="guide-chapter"><h2>{h}</h2><p>{p1}</p><p>{p2}</p></section>' for h,p1,p2 in chapters)

for lang,folder in [('en','english'),('hi','hindi'),('kn','kannada')]:
    for who,file in [('young','young-adult-starter.html'),('care','caregiver-starter.html')]:
        p=ROOT/'guides'/folder/file
        s=p.read_text()
        marker={'en':'<h2>Evidence behind this guide</h2>','hi':'<h2>इस गाइड के पीछे का evidence</h2>','kn':'<h2>ಈ ಗೈಡ್ ಹಿಂದಿರುವ evidence</h2>'}[lang]
        s=s.replace(marker,section_html(extra[lang][who])+marker)
        p.write_text(s)

def localize_visible(html,lang):
    parts=re.split(r'(<[^>]+>)',html)
    for i in range(0,len(parts),2):
        x=parts[i]
        for a,b in translations[lang].items(): x=x.replace(a,b)
        protected=[]
        def hold(m):
            token=f'¤{len(protected)}¤'; protected.append((token,m.group(0))); return token
        x=re.sub(r'\([A-Za-z][^)]*\)',hold,x)
        saved=[]
        for a,b in sorted(terms[lang].items(),key=lambda z:-len(z[0])):
            token=f'§{len(saved)}§'
            x,n=re.subn(r'(?<![A-Za-z])'+re.escape(a)+r'(?![A-Za-z])',token,x)
            if n: saved.append((token,b))
        for token,b in saved: x=x.replace(token,b)
        for token,b in protected: x=x.replace(token,b)
        parts[i]=x
    return ''.join(parts)

for lang,folder in [('hi','hindi'),('kn','kannada')]:
    files=list((ROOT/'guides'/folder).glob('*.html'))+list((ROOT/'situations'/folder).glob('*.html'))+list((ROOT/'activities'/folder).glob('*.html'))
    for p in files: p.write_text(localize_visible(p.read_text(),lang))

print('Expanded starter guides and transliterated borrowed terms.')
